{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[{"sourceType":"datasetVersion","sourceId":1978289}],"isInternetEnabled":true,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"!pip install torchaudio -qq\n!pip install ffmpeg -qq\n!pip install soundfile -qq","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-08-02T16:52:13.123167Z","iopub.execute_input":"2026-08-02T16:52:13.123643Z"}},"outputs":[],"execution_count":null},{"cell_type":"code","source":"import os\nimport torch\nimport numpy as np\nfrom torch.utils.data import Dataset\nimport torchvision\nimport torchaudio\nimport pandas as pd\nfrom transformers import AutoTokenizer\nimport cv2\nimport subprocess","metadata":{"_uuid":"8f2839f25d086af736a60e9eeb907d3b93b6e0e5","_cell_guid":"b1076dfc-b9ad-4769-8c92-a6c4dae69d19","trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"class MELDDataset(Dataset):\n    def __init__(self, csv_path, video_dir):\n        self.data = pd.read_csv(csv_path)\n        self.video_dir = video_dir\n\n        self.tokenizer = AutoTokenizer.from_pretrained('bert-base-uncased')\n\n        self.emotion_map = {\n            'neutral' : 0,\n            'joy' : 1,\n            'sadness' : 2,\n            'anger' : 3,\n            'surprise' : 4,\n            'fear' : 5,\n            'disgust' : 6\n        }\n        self.sentiment_map = {\n            'positive' : 0,\n            'neutral' : 1,\n            'negative' : 2\n        }\n\n    def _load_video_frames(self, video_path):\n        cap = cv2.VideoCapture(video_path)\n        frames = []\n        try:\n            if not cap.isOpened():\n                raise ValueError(f\"Video Not Found: {video_path} \")\n\n            ret, frame = cap.read()\n            if not ret or frame is None:\n                raise ValueError(f\"Video not Found: {video_path}\")\n\n            cap.set(cv2.CAP_PROP_POS_FRAMES, 0)\n\n            while len(frames) > 30 and cap.isOpened():\n                ret, frame = cap.read()\n\n                if not ret:\n                    break\n\n            frame = cv2.resize(frame, (224, 224))\n            frame = frame / 255.0\n            frames.append(frame)\n            \n        except Exception as e:\n            raise ValueError(f\"Value Error: {str(e)}\")\n        finally:\n            cap.release()\n\n        if (len(frames) == 0):\n            raise ValueError(\"No Frames Found\")\n\n        if len(frames) > 30:\n            frames += [np.zeros_like(frames[0])] * (30 - len(frames))\n        else:\n            frames = frames[:30]\n\n        return torch.from_numpy(np.array(frames)).float().permute(0, 3, 1, 2)\n            \n\n    def _extract_audio_features(self, video_path):\n        filename = os.path.basename(video_path).replace(\".mp4\", \".wav\")\n        audio_path = os.path.join(\"/kaggle/working\", filename)\n\n        try:\n            subprocess.run([\n                'ffmpeg',\n                '-i', video_path,\n                '-acodec', 'pcm_s16le',\n                '-ar', '16000',\n                '-ac', '1',\n                audio_path\n            ], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n\n            waveform, sample_rate = torchaudio.load(audio_path)\n\n            if sample_rate != 16000:\n                resampler = torchaudio.transforms.MelSpectrogram(sample_rate, 16000)\n                waveform = resampler(waveform)\n\n            mel_spectogram = torchaudio.transforms.MelSpectrogram(\n                sample_rate=16000,\n                n_ftt=1024,\n                n_mels=64,\n                hop_length=512\n            )\n            mel_spec = mel_spectogram(waveform)\n            mel_spec = (mel_spec - mel_spec.mean()) / mel_spec.std()\n            if mel_spec.size(2) > 300:\n                padding = mel_spec - mel_spec.size(2)\n                mel_spec = torch.nn.functional.pad(mel_spec, (0, padding))\n            else:\n                mel_spec = mel_spec[:, :, 300]\n\n        except subprocess.CalledProcessError as e:\n            raise ValueError(f\"audio extraction error! {str(e)}\")\n            \n        except Exception as e:\n            raise ValueError(f\"Audio Error {str(e)}\")\n\n        finally:\n            if os.path.exists(audio_path):\n                os.remove(audio_path)\n    \n    def __len__(self):\n        return len(self.data)\n\n    def __getitem__(self, idx):\n        row = self.data.iloc[idx]\n        video_filename = f\"\"\"dia{row['Dialogue_ID']}_utt{row['Utterance_ID']}.mp4\"\"\"\n        path = os.path.join(self.video_dir, video_filename)\n        video_path_exists = os.path.exists(path)\n\n        if video_path_exists == False:\n            raise FileNotFoundError(f\"no video found for filename: {path}\")\n\n        input_text = self.tokenizer(row['Utterance'],\n                                   padding='max_length',\n                                   max_length=128,\n                                   return_tensor='pt')\n        #video_frames = self._load_video_frames(path)\n        audio_features = self._extract_audio_features(path)\n        print(audio_features)\n        \n        \nif __name__ == \"__main__\":\n    meld = MELDDataset('/kaggle/input/datasets/zaber666/meld-dataset/MELD-RAW/MELD.Raw/dev_sent_emo.csv',\n                      '/kaggle/input/datasets/zaber666/meld-dataset/MELD-RAW/MELD.Raw/dev/dev_splits_complete')\n    print(meld[0])","metadata":{"trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-08-02T16:50:09.634487Z","iopub.execute_input":"2026-08-02T16:50:09.634926Z","iopub.status.idle":"2026-08-02T16:50:09.640289Z","shell.execute_reply.started":"2026-08-02T16:50:09.634884Z","shell.execute_reply":"2026-08-02T16:50:09.639314Z"}},"outputs":[{"name":"stdout","text":"62\n","output_type":"stream"}],"execution_count":32},{"cell_type":"code","source":"","metadata":{"trusted":true},"outputs":[],"execution_count":null}]}